  constraint business_profiles_lead_sources_check CHECK ((cardinality(lead_sources) > 0)),
  constraint business_profiles_monthly_volume_range_check CHECK ((monthly_volume_range = ANY (ARRAY['0_25'::text, '26_100'::text, '101_250'::text, '251_500'::text, '500_plus'::text]))),
  constraint business_profiles_npn_check CHECK ((npn ~ '^[0-9]{1,10}$'::text)),
