  constraint tenants_pkey PRIMARY KEY (id)
);

create table if not exists public.trial_reminders (
  id uuid default gen_random_uuid() not null,
  subscription_id uuid not null,
  kind trial_reminder_kind not null,
  due_at timestamp with time zone not null,
  sent_at timestamp with time zone default now() not null,
  delivered boolean default false not null,
  trial_ends_at timestamp with time zone not null,
  constraint trial_reminders_pkey PRIMARY KEY (id),
  constraint trial_reminders_subscription_id_kind_trial_ends_at_key UNIQUE (subscription_id, kind, trial_ends_at)
);

create table if not exists public.usage_events (
  id uuid default gen_random_uuid() not null,
  tenant_id uuid not null,
  meter_key text not null,
  qty integer not null,
  ts timestamp with time zone default now() not null,
  ref text,
  idempotency_key text not null,
  period_start timestamp with time zone not null,
  constraint usage_events_pkey PRIMARY KEY (id)
);

create table if not exists public.usage_totals (
  tenant_id uuid not null,
  meter_key text not null,
  period_start timestamp with time zone not null,
  used_qty integer default 0 not null,
  updated_at timestamp with time zone default now() not null,
  constraint usage_totals_pkey PRIMARY KEY (tenant_id, meter_key, period_start)
);

create table if not exists public.user_invitations (
  id uuid default gen_random_uuid() not null,
  user_id uuid not null,
  token_hash text not null,
  expires_at timestamp with time zone not null,
  accepted_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  created_by uuid,
  purpose user_token_purpose default 'invite'::user_token_purpose not null,
  new_email text,
  constraint user_invitations_new_email_only_for_change CHECK (((purpose = 'email_change'::user_token_purpose) = (new_email IS NOT NULL))),
  constraint user_invitations_pkey PRIMARY KEY (id),
  constraint user_invitations_token_hash_key UNIQUE (token_hash)
);

create table if not exists public.users (
  id uuid default gen_random_uuid() not null,
  email text not null,
  password_hash text,
  name text not null,
  phone text,
  status user_status default 'active'::user_status not null,
  last_login_at timestamp with time zone,
  created_at timestamp with time zone default now() not null,
  suspended_at timestamp with time zone,
  suspension_reason text,
  constraint users_suspension_fields_consistent CHECK (((status = 'suspended'::user_status) = (suspended_at IS NOT NULL))),
  constraint users_pkey PRIMARY KEY (id),
  constraint users_email_key UNIQUE (email)
);

create table if not exists public.webhook_events (
  id uuid default gen_random_uuid() not null,
  provider text default 'whop'::text not null,
  event_id text not null,
  event_type text not null,
  occurred_at timestamp with time zone,
  received_at timestamp with time zone default now() not null,
  payload jsonb not null,
  tenant_id uuid,
  processed_at timestamp with time zone,
  process_error text,
  attempts integer default 0 not null,
  constraint webhook_events_pkey PRIMARY KEY (id),
  constraint webhook_events_provider_event_id_key UNIQUE (provider, event_id)
);

create table if not exists public.whop_plans (
  id uuid default gen_random_uuid() not null,
  plan_id uuid not null,
  billing_cycle billing_cycle not null,
  whop_plan_id text not null,
  whop_product_id text,
  price_cents integer not null,
  created_at timestamp with time zone default now() not null,
  constraint whop_plans_pkey PRIMARY KEY (id),
  constraint whop_plans_plan_id_billing_cycle_key UNIQUE (plan_id, billing_cycle),
  constraint whop_plans_whop_plan_id_key UNIQUE (whop_plan_id)
);


