-- --------------------------------------------------------------------------
-- Views
-- --------------------------------------------------------------------------

create or replace view public.admin_legal_acceptance_stats as
 SELECT id AS document_id,
    doc_type,
    version,
    title,
    is_draft,
    requires_reacceptance,
    published_at,
    ( SELECT count(*) AS count
           FROM users u
          WHERE u.status <> 'inactive'::user_status) AS eligible_users,
    ( SELECT count(*) AS count
           FROM legal_acceptances a
          WHERE a.document_id = c.id) AS accepted_count
   FROM current_legal_documents c;

create or replace view public.admin_plan_list as
 SELECT DISTINCT ON (code) id,
    code,
    version,
    name,
    plan_type,
    description,
    is_public,
    is_archived,
    sort_order,
    created_at,
    ( SELECT count(*) AS count
           FROM plans v
          WHERE v.code = p.code) AS version_count,
    ( SELECT count(*) AS count
           FROM subscriptions s
             JOIN plans sp ON sp.id = s.plan_id
          WHERE sp.code = p.code AND s.status <> 'cancelled'::subscription_status) AS subscriber_count,
    ( SELECT count(*) AS count
           FROM subscriptions s
             JOIN plans sp ON sp.id = s.plan_id
          WHERE sp.code = p.code) AS ever_subscribed_count
   FROM plans p
  ORDER BY code, version DESC;

create or replace view public.admin_trials_in_flight as
 SELECT s.id AS subscription_id,
    s.tenant_id,
    t.name AS tenant_name,
    p.name AS plan_name,
    p.code AS plan_code,
    s.billing_cycle,
    s.started_at,
    s.trial_ends_at,
    GREATEST(0::numeric, ceil(EXTRACT(epoch FROM s.trial_ends_at - now()) / 86400::numeric))::integer AS days_remaining,
    GREATEST(0::numeric, floor(EXTRACT(epoch FROM now() - s.started_at) / 86400::numeric))::integer AS days_elapsed,
    owner_user.email AS owner_email,
    owner_user.name AS owner_name,
    owner_user.last_login_at,
    pp.provider_customer_id IS NOT NULL AS has_payment_method,
    bp.business_name
   FROM subscriptions s
     JOIN tenants t ON t.id = s.tenant_id
     JOIN plans p ON p.id = s.plan_id
     LEFT JOIN LATERAL ( SELECT u.email,
            u.name,
            u.last_login_at
           FROM tenant_users tu
             JOIN users u ON u.id = tu.user_id
          WHERE tu.tenant_id = s.tenant_id AND tu.role = 'owner'::tenant_user_role
         LIMIT 1) owner_user ON true
     LEFT JOIN payment_providers pp ON pp.tenant_id = s.tenant_id AND pp.is_default
     LEFT JOIN business_profiles bp ON bp.tenant_id = s.tenant_id
  WHERE s.status = 'trialing'::subscription_status AND s.trial_ends_at IS NOT NULL;

create or replace view public.admin_user_list as
 SELECT u.id,
    u.name,
    u.email,
    u.phone,
    u.status,
    u.last_login_at,
    u.created_at,
    tu.tenant_id,
    t.name AS tenant_name,
    tu.role AS tenant_role,
    t.plan_code,
    u.password_hash IS NOT NULL AS has_password,
    u.suspended_at,
    u.suspension_reason,
    ( SELECT count(DISTINCT le.ip) AS count
           FROM login_events le
          WHERE le.user_id = u.id AND le.success AND le.ip IS NOT NULL AND le.ts > (now() - '24:00:00'::interval)) AS distinct_ips_24h
   FROM users u
     LEFT JOIN tenant_users tu ON tu.user_id = u.id
     LEFT JOIN tenants t ON t.id = tu.tenant_id;

create or replace view public.current_legal_documents as
 SELECT DISTINCT ON (doc_type) id,
    doc_type,
    version,
    effective_date,
    title,
    change_summary,
    requires_reacceptance,
    is_draft,
    published_at
   FROM legal_documents
  ORDER BY doc_type, version DESC;


-- --------------------------------------------------------------------------
-- Functions
-- --------------------------------------------------------------------------

CREATE OR REPLACE FUNCTION public.adjust_tenant_credit(p_tenant_id uuid, p_delta_cents integer)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare v_balance integer;
begin
  insert into public.tenant_credits (tenant_id, balance_cents)
  values (p_tenant_id, 0)
  on conflict (tenant_id) do nothing;

  update public.tenant_credits
     set balance_cents = balance_cents + p_delta_cents,
         updated_at = now()
   where tenant_id = p_tenant_id
  returning balance_cents into v_balance;

  return v_balance;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_apply_coupon(p_subscription_id uuid, p_coupon_id uuid, p_applied_by uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_coupon public.coupons%rowtype;
  v_periods integer;
begin
  -- Locked for the duration, so two admins claiming the last slot cannot both read the old count.
  select * into v_coupon from public.coupons where id = p_coupon_id for update;

  if not found then return 'not_found'; end if;
  if not v_coupon.is_active then return 'inactive'; end if;
  if v_coupon.expires_at is not null and v_coupon.expires_at <= now() then return 'expired'; end if;
  if v_coupon.max_redemptions is not null and v_coupon.redeemed_count >= v_coupon.max_redemptions then
    return 'exhausted';
  end if;

  -- "One at a time, reject the second" — checked here as well as by the unique index, so the
  -- caller gets a named reason rather than a constraint violation.
  if exists (
    select 1 from public.subscription_coupons
     where subscription_id = p_subscription_id and is_active
  ) then
    return 'already_has_coupon';
  end if;

  v_periods := case
    when v_coupon.duration = 'forever' then null
    when v_coupon.duration = 'once' then 1
    else v_coupon.duration_periods
  end;

  insert into public.subscription_coupons (subscription_id, coupon_id, applied_by, periods_remaining)
  values (p_subscription_id, p_coupon_id, p_applied_by, v_periods);

  update public.coupons set redeemed_count = redeemed_count + 1 where id = p_coupon_id;

  return 'ok';
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_assign_subscription(p_tenant_id uuid, p_plan_id uuid, p_billing_cycle billing_cycle, p_start timestamp with time zone DEFAULT now())
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare
  v_id uuid;
  v_trial_days integer;
  v_price integer;
  v_status subscription_status;
  v_trial_ends timestamptz;
begin
  if exists (
    select 1 from subscriptions
    where tenant_id = p_tenant_id and status <> 'cancelled'
  ) then
    raise exception 'already_subscribed' using errcode = 'raise_exception';
  end if;

  -- The chosen cycle must actually be offered by the plan (SA-2.4: a null price means that
  -- cycle isn't sold).
  select case p_billing_cycle
           when 'monthly' then price_monthly_cents
           when 'quarterly' then price_quarterly_cents
           else price_yearly_cents
         end,
         trial_days
    into v_price, v_trial_days
  from plan_prices where plan_id = p_plan_id;

  if v_price is null then
    raise exception 'cycle_not_offered' using errcode = 'raise_exception';
  end if;

  if coalesce(v_trial_days, 0) > 0 then
    v_status := 'trialing';
    v_trial_ends := p_start + (v_trial_days || ' days')::interval;
  else
    v_status := 'active';
    v_trial_ends := null;
  end if;

  insert into subscriptions (
    tenant_id, plan_id, status, billing_cycle, started_at,
    current_period_start, current_period_end, trial_ends_at
  )
  values (
    p_tenant_id, p_plan_id, v_status, p_billing_cycle, p_start,
    p_start, period_end_for(p_start, p_billing_cycle), v_trial_ends
  )
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_attach_addon(p_subscription_id uuid, p_addon_id uuid, p_override_availability boolean DEFAULT false, p_attached_by uuid DEFAULT NULL::uuid)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare
  v_sub_cycle billing_cycle;
  v_plan_id uuid;
  v_addon_cycle billing_cycle;
  v_active boolean;
  v_available boolean;
  v_id uuid;
begin
  select billing_cycle, plan_id into v_sub_cycle, v_plan_id
  from subscriptions where id = p_subscription_id;

  if not found then
    raise exception 'subscription_not_found' using errcode = 'no_data_found';
  end if;

  select billing_cycle, is_active into v_addon_cycle, v_active
  from addons where id = p_addon_id;

  if not found then
    raise exception 'addon_not_found' using errcode = 'no_data_found';
  end if;

  if not v_active then
    raise exception 'addon_inactive' using errcode = 'raise_exception';
  end if;

  if v_addon_cycle <> v_sub_cycle then
    raise exception 'cycle_mismatch:%:%', v_addon_cycle, v_sub_cycle using errcode = 'raise_exception';
  end if;

  select exists (
    select 1 from plan_available_addons
    where plan_id = v_plan_id and addon_id = p_addon_id
  ) into v_available;

  if not v_available and not p_override_availability then
    raise exception 'not_available_on_plan' using errcode = 'raise_exception';
  end if;

  insert into subscription_addons (subscription_id, addon_id, attached_by, availability_overridden)
  values (p_subscription_id, p_addon_id, p_attached_by, not v_available)
  returning id into v_id;

  return v_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_cancel_subscription(p_subscription_id uuid, p_reason text, p_immediate boolean DEFAULT false)
 RETURNS TABLE(cancelled_now boolean, effective_at timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
declare
  v_period_end timestamptz;
begin
  select current_period_end into v_period_end
  from subscriptions where id = p_subscription_id for update;

  if not found then
    raise exception 'subscription_not_found' using errcode = 'no_data_found';
  end if;

  if p_immediate then
    update subscriptions
    set status = 'cancelled', cancelled_at = now(), cancel_reason = p_reason,
        cancel_at_period_end = false, pending_plan_id = null
    where id = p_subscription_id;
    return query select true, now();
  else
    update subscriptions
    set cancel_at_period_end = true, cancel_reason = p_reason, status = 'cancelling'
    where id = p_subscription_id;
    return query select false, v_period_end;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_change_subscription_plan(p_subscription_id uuid, p_new_plan_id uuid, p_apply_now boolean)
 RETURNS TABLE(applied_now boolean, effective_at timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
declare
  v_cycle billing_cycle;
  v_period_end timestamptz;
  v_price integer;
begin
  select billing_cycle, current_period_end into v_cycle, v_period_end
  from subscriptions where id = p_subscription_id for update;

  if not found then
    raise exception 'subscription_not_found' using errcode = 'no_data_found';
  end if;

  select case v_cycle
           when 'monthly' then price_monthly_cents
           when 'quarterly' then price_quarterly_cents
           else price_yearly_cents
         end
    into v_price
  from plan_prices where plan_id = p_new_plan_id;

  if v_price is null then
    raise exception 'cycle_not_offered' using errcode = 'raise_exception';
  end if;

  if p_apply_now then
    update subscriptions
    set plan_id = p_new_plan_id, pending_plan_id = null
    where id = p_subscription_id;
    return query select true, now();
  else
    update subscriptions
    set pending_plan_id = p_new_plan_id
    where id = p_subscription_id;
    return query select false, v_period_end;
  end if;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_create_plan_version(p_plan_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
AS $function$
declare
  v_new_id uuid;
  v_code text;
  v_next integer;
begin
  select code into v_code from plans where id = p_plan_id;
  if not found then
    raise exception 'plan_not_found' using errcode = 'no_data_found';
  end if;

  select max(version) + 1 into v_next from plans where code = v_code;

  insert into plans (code, version, name, plan_type, description, is_public, is_archived, sort_order)
  select code, v_next, name, plan_type, description, is_public, false, sort_order
  from plans where id = p_plan_id
  returning id into v_new_id;

  insert into plan_features (plan_id, feature_key)
  select v_new_id, feature_key from plan_features where plan_id = p_plan_id;

  insert into plan_prices (
    plan_id, price_monthly_cents, price_quarterly_cents, price_yearly_cents,
    setup_fee_cents, trial_days, currency
  )
  select v_new_id, price_monthly_cents, price_quarterly_cents, price_yearly_cents,
         setup_fee_cents, trial_days, currency
  from plan_prices where plan_id = p_plan_id;

  return v_new_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_create_user(p_name text, p_email text, p_phone text, p_tenant_id uuid, p_new_tenant_name text, p_role tenant_user_role, p_token_hash text, p_expires_at timestamp with time zone, p_created_by uuid)
 RETURNS TABLE(user_id uuid, tenant_id uuid)
 LANGUAGE plpgsql
AS $function$
declare
  v_user_id uuid;
  v_tenant_id uuid;
  v_plan uuid;
  v_max_seats integer;
  v_used integer;
begin
  if p_tenant_id is null and (p_new_tenant_name is null or btrim(p_new_tenant_name) = '') then
    raise exception 'either an existing tenant or a new tenant name is required';
  end if;

  if p_tenant_id is not null then
    v_tenant_id := p_tenant_id;

    v_plan := tenant_current_plan(v_tenant_id);
    if v_plan is not null then
      select pl.max_seats into v_max_seats from plan_limits pl where pl.plan_id = v_plan;

      if v_max_seats is not null then
        v_used := tenant_seats_used(v_tenant_id);
        if v_used >= v_max_seats then
          raise exception 'seat_limit_reached:%:%', v_used, v_max_seats
            using errcode = 'raise_exception';
        end if;
      end if;
    end if;
  else
    insert into tenants (name, status) values (p_new_tenant_name, 'provisioning')
    returning id into v_tenant_id;
  end if;

  insert into users (name, email, phone, status)
  values (p_name, lower(p_email), nullif(btrim(coalesce(p_phone, '')), ''), 'active')
  returning id into v_user_id;

  insert into tenant_users (tenant_id, user_id, role, accepted_at)
  values (v_tenant_id, v_user_id, p_role, null);

  insert into user_invitations (user_id, token_hash, expires_at, created_by)
  values (v_user_id, p_token_hash, p_expires_at, p_created_by);

  return query select v_user_id, v_tenant_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_detach_addon(p_subscription_addon_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
AS $function$
begin
  update subscription_addons
  set detached_at = now()
  where id = p_subscription_addon_id and detached_at is null;

  return found;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_login_activity_stats()
 RETURNS TABLE(logins_today bigint, logins_this_week bigint, failed_today bigint, active_last_15_min bigint)
 LANGUAGE sql
 STABLE
AS $function$
  select
    count(*) filter (where success and ts >= date_trunc('day', now())) as logins_today,
    count(*) filter (where success and ts >= date_trunc('week', now())) as logins_this_week,
    count(*) filter (where not success and ts >= date_trunc('day', now())) as failed_today,
    count(distinct case
      when success and ts >= now() - interval '15 minutes'
      then coalesce(user_id, admin_id)
    end) as active_last_15_min
  from login_events;
$function$;

CREATE OR REPLACE FUNCTION public.admin_save_plan_version(p_plan_id uuid, p_feature_keys text[], p_price_monthly integer, p_price_quarterly integer, p_price_yearly integer, p_setup_fee integer, p_trial_days integer)
 RETURNS TABLE(target_plan_id uuid, target_version integer, created_new_version boolean)
 LANGUAGE plpgsql
AS $function$
declare
  v_target uuid;
  v_subs integer;
  v_new boolean := false;
  v_version integer;
  v_archived_grants text[];
begin
  if p_feature_keys is null or coalesce(array_length(p_feature_keys, 1), 0) = 0 then
    raise exception 'no_features' using errcode = 'raise_exception';
  end if;

  -- Captured before any delete: archived features stay granted to a plan that already had them
  -- (SA-2.1), and the picker can't offer them, so the submitted list alone would revoke them.
  select array_agg(pf.feature_key) into v_archived_grants
  from plan_features pf
  join features f on f.feature_key = pf.feature_key
  where pf.plan_id = p_plan_id and f.is_archived;

  select count(*) into v_subs
  from subscriptions s
  where s.plan_id = p_plan_id and s.status <> 'cancelled';

  if v_subs > 0 then
    v_target := admin_create_plan_version(p_plan_id);
    v_new := true;
  else
    v_target := p_plan_id;
  end if;

  delete from plan_features where plan_id = v_target;

  insert into plan_features (plan_id, feature_key)
  select v_target, k from unnest(p_feature_keys) as k
  on conflict do nothing;

  if v_archived_grants is not null then
    insert into plan_features (plan_id, feature_key)
    select v_target, k from unnest(v_archived_grants) as k
    on conflict do nothing;
  end if;

  -- No cycle priced = not sellable = no price row, rather than a row of nulls.
  if p_price_monthly is null and p_price_quarterly is null and p_price_yearly is null then
    delete from plan_prices where plan_id = v_target;
  else
    insert into plan_prices (
      plan_id, price_monthly_cents, price_quarterly_cents, price_yearly_cents,
      setup_fee_cents, trial_days, currency, updated_at
    )
    values (
      v_target, p_price_monthly, p_price_quarterly, p_price_yearly,
      coalesce(p_setup_fee, 0), coalesce(p_trial_days, 0), 'USD', now()
    )
    on conflict (plan_id) do update set
      price_monthly_cents = excluded.price_monthly_cents,
      price_quarterly_cents = excluded.price_quarterly_cents,
      price_yearly_cents = excluded.price_yearly_cents,
      setup_fee_cents = excluded.setup_fee_cents,
      trial_days = excluded.trial_days,
      updated_at = now();
  end if;

  select version into v_version from plans where id = v_target;

  return query select v_target, v_version, v_new;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_update_plan(p_plan_id uuid, p_code text, p_name text, p_description text, p_is_public boolean, p_is_archived boolean, p_sort_order integer)
 RETURNS TABLE(old_code text, old_name text, old_is_archived boolean, new_code text, new_name text, new_is_archived boolean)
 LANGUAGE plpgsql
AS $function$
declare
  v_old_code text;
  v_old_name text;
  v_old_archived boolean;
  v_subscribers integer;
begin
  select code, name, is_archived into v_old_code, v_old_name, v_old_archived
  from plans where id = p_plan_id for update;

  if not found then
    raise exception 'plan_not_found' using errcode = 'no_data_found';
  end if;

  if p_code is distinct from v_old_code then
    select count(*) into v_subscribers
    from subscriptions s
    join plans pl on pl.id = s.plan_id
    where pl.code = v_old_code;

    if v_subscribers > 0 then
      raise exception 'code_locked' using errcode = 'raise_exception';
    end if;

    -- Renaming the code renames every version of it, so they stay one family.
    update plans set code = p_code where code = v_old_code;
  end if;

  update plans
  set name = p_name,
      description = nullif(btrim(coalesce(p_description, '')), ''),
      is_public = p_is_public,
      is_archived = p_is_archived,
      sort_order = p_sort_order
  where id = p_plan_id;

  return query select v_old_code, v_old_name, v_old_archived, p_code, p_name, p_is_archived;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_update_user(p_user_id uuid, p_name text, p_phone text, p_role tenant_user_role)
 RETURNS TABLE(old_name text, old_phone text, old_role tenant_user_role, new_name text, new_phone text, new_role tenant_user_role)
 LANGUAGE plpgsql
AS $function$
declare
  v_old_name text;
  v_old_phone text;
  v_old_role tenant_user_role;
  v_tenant_id uuid;
  v_owner_count int;
begin
  select u.name, u.phone into v_old_name, v_old_phone
  from users u where u.id = p_user_id
  for update;

  if not found then
    raise exception 'user not found' using errcode = 'no_data_found';
  end if;

  select tu.role, tu.tenant_id into v_old_role, v_tenant_id
  from tenant_users tu where tu.user_id = p_user_id
  for update;

  -- A tenant must always keep at least one owner. Checked here, inside the transaction and
  -- holding the row lock, so two concurrent demotions cannot both pass and orphan the tenant.
  if v_old_role = 'owner' and p_role <> 'owner' then
    select count(*) into v_owner_count
    from tenant_users
    where tenant_id = v_tenant_id and role = 'owner';

    if v_owner_count <= 1 then
      raise exception 'last_owner' using errcode = 'raise_exception';
    end if;
  end if;

  update users
  set name = p_name,
      phone = nullif(btrim(coalesce(p_phone, '')), '')
  where id = p_user_id;

  update tenant_users set role = p_role where user_id = p_user_id;

  return query select v_old_name, v_old_phone, v_old_role, p_name, p_phone, p_role;
end;
$function$;

CREATE OR REPLACE FUNCTION public.admin_user_stats()
 RETURNS TABLE(total bigint, active bigint, inactive bigint, suspended bigint, signed_up_this_month bigint)
 LANGUAGE sql
 STABLE
AS $function$
  select
    count(*) filter (where status <> 'deleted') as total,
    count(*) filter (where status = 'active') as active,
    count(*) filter (where status = 'inactive') as inactive,
    count(*) filter (where status = 'suspended') as suspended,
    count(*) filter (
      where status <> 'deleted'
        and created_at >= date_trunc('month', now())
    ) as signed_up_this_month
  from users;
$function$;

CREATE OR REPLACE FUNCTION public.advance_billing_periods()
 RETURNS TABLE(subscription_id uuid, action text, new_period_start timestamp with time zone, new_period_end timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
declare
  r record;
  v_new_start timestamptz;
  v_new_end timestamptz;
  v_action text;
begin
  for r in
    select * from subscriptions
    where status <> 'cancelled'
      and current_period_end is not null
      and current_period_end <= now()
    order by current_period_end
    for update
  loop
    if r.cancel_at_period_end then
      update subscriptions
      set status = 'cancelled', cancelled_at = now(), cancel_at_period_end = false
      where id = r.id;

      perform refresh_tenant_entitlement(r.tenant_id);

      subscription_id := r.id; action := 'cancelled';
      new_period_start := r.current_period_start; new_period_end := r.current_period_end;
      return next;
      continue;
    end if;

    v_new_start := r.current_period_end;
    v_new_end := period_end_for(v_new_start, r.billing_cycle);

    if r.pending_plan_id is not null then
      update subscriptions
      set plan_id = r.pending_plan_id, pending_plan_id = null,
          current_period_start = v_new_start, current_period_end = v_new_end,
          status = case when r.status = 'trialing' then 'active'::subscription_status else r.status end
      where id = r.id;
      v_action := 'plan_changed';
    else
      update subscriptions
      set current_period_start = v_new_start, current_period_end = v_new_end,
          status = case when r.status = 'trialing' then 'active'::subscription_status else r.status end
      where id = r.id;
      v_action := 'period_rolled';
    end if;

    -- Always refresh: even a plain roll resets meter usage, which the blob carries.
    perform refresh_tenant_entitlement(r.tenant_id);

    subscription_id := r.id; action := v_action;
    new_period_start := v_new_start; new_period_end := v_new_end;
    return next;
  end loop;
end;
$function$;

CREATE OR REPLACE FUNCTION public.allocate_document_number(p_series text, p_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare
  v_year  integer := extract(year from p_at)::integer;
  v_month integer := extract(month from p_at)::integer;
  v_next  integer;
begin
  insert into public.invoice_counters (series, year, month, next_number)
  values (p_series, v_year, v_month, 1)
  on conflict (series, year, month) do nothing;

  update public.invoice_counters
     set next_number = next_number + 1
   where series = p_series and year = v_year and month = v_month
  returning next_number - 1 into v_next;

  return format('%s-%s-%s-%s', p_series, v_year, lpad(v_month::text, 2, '0'), lpad(v_next::text, 4, '0'));
end;
$function$;

CREATE OR REPLACE FUNCTION public.allocate_invoice_number(p_at timestamp with time zone)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
begin
  return public.allocate_document_number('INV', p_at);
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_coupon_redemption(p_coupon_id uuid)
 RETURNS text
 LANGUAGE plpgsql
AS $function$
declare v_row public.coupons%rowtype;
begin
  select * into v_row from public.coupons where id = p_coupon_id for update;

  if not found then return 'not_found'; end if;
  if not v_row.is_active then return 'inactive'; end if;
  if v_row.expires_at is not null and v_row.expires_at <= now() then return 'expired'; end if;
  if v_row.max_redemptions is not null and v_row.redeemed_count >= v_row.max_redemptions then
    return 'exhausted';
  end if;

  update public.coupons
     set redeemed_count = redeemed_count + 1
   where id = p_coupon_id;

  return 'ok';
end;
$function$;

CREATE OR REPLACE FUNCTION public.claim_rate_limit(p_key text, p_max integer, p_window_seconds integer)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_window timestamptz;
  v_hits   integer;
begin
  -- Floor to the start of the current fixed window.
  v_window := to_timestamp(floor(extract(epoch from now()) / p_window_seconds) * p_window_seconds);

  insert into public.rate_limits (bucket_key, window_start, hits)
  values (p_key, v_window, 1)
  on conflict (bucket_key, window_start)
    do update set hits = public.rate_limits.hits + 1
  returning hits into v_hits;

  return v_hits <= p_max;
end;
$function$;

CREATE OR REPLACE FUNCTION public.clear_reacceptance_requirement(p_document_id uuid)
 RETURNS legal_documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_row public.legal_documents;
begin
  update public.legal_documents
     set requires_reacceptance = false
   where id = p_document_id
  returning * into v_row;

  if not found then raise exception 'no such legal document'; end if;
  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.complete_signup_email_verification(p_token_hash text)
 RETURNS TABLE(user_id uuid, tenant_id uuid, email text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_token public.user_invitations%rowtype;
  v_tenant_id uuid;
  v_email text;
begin
  select invitation.*
    into v_token
    from public.user_invitations invitation
   where invitation.token_hash = p_token_hash
     and invitation.purpose = 'email_verification'
     and invitation.accepted_at is null
     and invitation.expires_at > now()
   for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'VERIFICATION_INVALID_OR_EXPIRED';
  end if;

  select membership.tenant_id
    into v_tenant_id
    from public.tenant_users membership
   where membership.user_id = v_token.user_id
     and membership.role = 'owner'
   for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'OWNER_MEMBERSHIP_NOT_FOUND';
  end if;

  update public.users as account
     set status = 'active'
   where account.id = v_token.user_id
     and account.status = 'pending_verification'
  returning account.email into v_email;

  if not found then
    raise exception using errcode = 'P0001', message = 'ACCOUNT_NOT_PENDING_VERIFICATION';
  end if;

  update public.user_invitations as invitation
     set accepted_at = now()
   where invitation.user_id = v_token.user_id
     and invitation.purpose = 'email_verification'
     and invitation.accepted_at is null;

  update public.tenant_users as membership
     set accepted_at = coalesce(membership.accepted_at, now())
   where membership.user_id = v_token.user_id
     and membership.tenant_id = v_tenant_id;

  update public.tenants as tenant
     set onboarding_state = 'business_profile'
   where tenant.id = v_tenant_id
     and tenant.onboarding_state = 'pending_verification';

  return query select v_token.user_id, v_tenant_id, v_email;
end;
$function$;

CREATE OR REPLACE FUNCTION public.compute_metrics_for_date(p_date date)
 RETURNS metrics_daily
 LANGUAGE plpgsql
AS $function$
declare
  v_row public.metrics_daily%rowtype;
  v_end timestamptz := (p_date + 1)::timestamptz;  -- exclusive upper bound
begin
  with active as (
    select s.id, s.tenant_id, s.plan_id, s.billing_cycle, s.status,
           public.monthly_equivalent_cents(s.plan_id, s.billing_cycle) as mrr,
           p.code as plan_code
      from public.subscriptions s
      join public.plans p on p.id = s.plan_id
     where s.started_at < v_end
       and (s.cancelled_at is null or s.cancelled_at >= v_end)
       -- Revenue-bearing only. A trial is not revenue yet and is counted separately; suspended and
       -- paused subscriptions are not being charged at all.
       and s.status in ('active', 'past_due', 'cancelling')
  ),
  trials as (
    select count(*)::integer as n
      from public.subscriptions
     where started_at < v_end
       and status = 'trialing'
       and (cancelled_at is null or cancelled_at >= v_end)
  ),
  started as (
    select coalesce(sum(public.monthly_equivalent_cents(plan_id, billing_cycle)), 0)::integer as mrr,
           count(*)::integer as n
      from public.subscriptions
     where started_at >= p_date::timestamptz and started_at < v_end
  ),
  churned as (
    select coalesce(sum(public.monthly_equivalent_cents(plan_id, billing_cycle)), 0)::integer as mrr,
           count(*)::integer as n
      from public.subscriptions
     where cancelled_at >= p_date::timestamptz and cancelled_at < v_end
  ),
  collected as (
    select coalesce(sum(amount_cents), 0)::integer as cents
      from public.payments
     where status = 'succeeded'
       and paid_at >= p_date::timestamptz and paid_at < v_end
  ),
  by_plan as (
    select jsonb_object_agg(plan_code, jsonb_build_object('customers', n, 'mrr_cents', mrr)) as breakdown
      from (select plan_code, count(*)::integer as n, sum(mrr)::integer as mrr
              from active group by plan_code) t
  )
  insert into public.metrics_daily (
    date, mrr_cents, arr_cents, new_mrr_cents, churned_mrr_cents, collected_cents,
    active_customers, new_customers, churned_customers, trials_active, plan_breakdown, computed_at
  )
  select
    p_date,
    coalesce((select sum(mrr) from active), 0)::integer,
    coalesce((select sum(mrr) from active), 0)::integer * 12,
    (select mrr from started),
    (select mrr from churned),
    (select cents from collected),
    (select count(distinct tenant_id) from active)::integer,
    (select n from started),
    (select n from churned),
    (select n from trials),
    coalesce((select breakdown from by_plan), '{}'::jsonb),
    now()
  on conflict (date) do update set
    mrr_cents = excluded.mrr_cents,
    arr_cents = excluded.arr_cents,
    new_mrr_cents = excluded.new_mrr_cents,
    churned_mrr_cents = excluded.churned_mrr_cents,
    collected_cents = excluded.collected_cents,
    active_customers = excluded.active_customers,
    new_customers = excluded.new_customers,
    churned_customers = excluded.churned_customers,
    trials_active = excluded.trials_active,
    plan_breakdown = excluded.plan_breakdown,
    computed_at = now()
  returning * into v_row;

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.consume_coupon_period(p_subscription_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare v_row public.subscription_coupons%rowtype;
begin
  select * into v_row from public.subscription_coupons
   where subscription_id = p_subscription_id and is_active
   for update;

  if not found then return -1; end if;
  -- Null is forever: nothing to consume.
  if v_row.periods_remaining is null then return -1; end if;

  update public.subscription_coupons
     set periods_remaining = periods_remaining - 1,
         is_active = (periods_remaining - 1) > 0,
         removed_at = case when (periods_remaining - 1) > 0 then null else now() end
   where id = v_row.id;

  return v_row.periods_remaining - 1;
end;
$function$;

CREATE OR REPLACE FUNCTION public.consume_user_email_change_token(p_token_hash text)
 RETURNS TABLE(user_id uuid, email text, accepted_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_token public.user_invitations%rowtype;
  v_accepted_at timestamptz := now();
begin
  select invitation.*
    into v_token
    from public.user_invitations invitation
   where invitation.token_hash = p_token_hash
     and invitation.purpose = 'email_change'
     and invitation.new_email is not null
     and invitation.accepted_at is null
     and invitation.expires_at > now()
   for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'EMAIL_CHANGE_TOKEN_INVALID_OR_EXPIRED';
  end if;

  begin
    update public.users account
       set email = lower(v_token.new_email)
     where account.id = v_token.user_id;
  exception
    when unique_violation then
      raise exception using errcode = 'P0001', message = 'EMAIL_ALREADY_REGISTERED';
  end;

  if not found then
    raise exception using errcode = 'P0001', message = 'EMAIL_CHANGE_USER_NOT_FOUND';
  end if;

  update public.user_invitations invitation
     set accepted_at = v_accepted_at
   where invitation.id = v_token.id
     and invitation.accepted_at is null;

  if not found then
    raise exception using errcode = 'P0001', message = 'EMAIL_CHANGE_TOKEN_ALREADY_USED';
  end if;

  return query select v_token.user_id, lower(v_token.new_email), v_accepted_at;
end;
$function$;

CREATE OR REPLACE FUNCTION public.consume_user_password_token(p_token_hash text, p_password_hash text)
 RETURNS TABLE(user_id uuid, purpose user_token_purpose, accepted_at timestamp with time zone)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_token public.user_invitations%rowtype;
  v_accepted_at timestamptz := now();
begin
  select invitation.*
    into v_token
    from public.user_invitations invitation
   where invitation.token_hash = p_token_hash
     and invitation.purpose in ('invite', 'password_reset')
     and invitation.accepted_at is null
     and invitation.expires_at > now()
   for update;

  if not found then
    raise exception using errcode = 'P0001', message = 'PASSWORD_TOKEN_INVALID_OR_EXPIRED';
  end if;

  update public.users account
     set password_hash = p_password_hash
   where account.id = v_token.user_id;

  if not found then
    raise exception using errcode = 'P0001', message = 'PASSWORD_TOKEN_USER_NOT_FOUND';
  end if;

  update public.user_invitations invitation
     set accepted_at = v_accepted_at
   where invitation.id = v_token.id
     and invitation.accepted_at is null;

  if not found then
    raise exception using errcode = 'P0001', message = 'PASSWORD_TOKEN_ALREADY_USED';
  end if;

  if v_token.purpose = 'invite' then
    update public.tenant_users membership
       set accepted_at = coalesce(membership.accepted_at, v_accepted_at)
     where membership.user_id = v_token.user_id;
  end if;

  return query select v_token.user_id, v_token.purpose, v_accepted_at;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_custom_invoice(p_tenant_id uuid, p_subscription_id uuid, p_reason text, p_due_at timestamp with time zone, p_created_by uuid, p_lines jsonb)
 RETURNS TABLE(invoice_id uuid, number text, total_cents integer)
 LANGUAGE plpgsql
AS $function$
declare
  v_number   text;
  v_id       uuid;
  v_subtotal integer := 0;
  v_discount integer := 0;
  v_total    integer;
  v_line     jsonb;
  v_position integer := 0;
begin
  if p_reason is null or length(trim(p_reason)) < 5 then
    raise exception 'a custom invoice needs a reason';
  end if;

  if jsonb_array_length(p_lines) = 0 then
    raise exception 'a custom invoice needs at least one line';
  end if;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    if (v_line ->> 'kind') in ('discount', 'credit') then
      v_discount := v_discount + abs((v_line ->> 'amount_cents')::integer);
    else
      v_subtotal := v_subtotal + (v_line ->> 'amount_cents')::integer;
    end if;
  end loop;

  v_total := v_subtotal - v_discount;
  if v_total <= 0 then
    raise exception 'a custom invoice must total more than zero';
  end if;

  v_number := public.allocate_invoice_number(now());

  -- Issued, not paid: unlike an invoice generated from a collected payment, nobody has paid this
  -- yet. This is the only path that produces an unpaid invoice, which is what finally exercises
  -- overdue, void and the manual mark-as-paid flow.
  insert into public.invoices (
    number, tenant_id, subscription_id, kind, reason, status,
    subtotal_cents, discount_cents, tax_cents, total_cents,
    issued_at, due_at, created_by, reconciliation
  ) values (
    v_number, p_tenant_id, p_subscription_id, 'custom', p_reason, 'issued',
    v_subtotal, v_discount, 0, v_total,
    now(), p_due_at, p_created_by, 'not_applicable'
  ) returning id into v_id;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    insert into public.invoice_lines (invoice_id, position, kind, label, quantity, unit_cents, amount_cents)
    values (
      v_id, v_position,
      coalesce((v_line ->> 'kind')::public.invoice_line_kind, 'plan'),
      v_line ->> 'label',
      coalesce((v_line ->> 'quantity')::numeric, 1),
      coalesce((v_line ->> 'unit_cents')::integer, (v_line ->> 'amount_cents')::integer),
      (v_line ->> 'amount_cents')::integer
    );
    v_position := v_position + 1;
  end loop;

  return query select v_id, v_number, v_total;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_invoice_for_payment(p_tenant_id uuid, p_subscription_id uuid, p_provider text, p_provider_payment_id text, p_provider_total_cents integer, p_period_start timestamp with time zone, p_period_end timestamp with time zone, p_paid_at timestamp with time zone, p_lines jsonb)
 RETURNS TABLE(invoice_id uuid, number text, created boolean, reconciliation text)
 LANGUAGE plpgsql
AS $function$
declare
  v_existing       public.invoices%rowtype;
  v_number         text;
  v_id             uuid;
  v_subtotal       integer := 0;
  v_discount       integer := 0;
  v_total          integer;
  v_reconciliation text;
  v_line           jsonb;
  v_position       integer := 0;
begin
  select * into v_existing
    from public.invoices
   where provider = p_provider and provider_payment_id = p_provider_payment_id;

  if found then
    return query select v_existing.id, v_existing.number, false, v_existing.reconciliation;
    return;
  end if;

  -- Discounts are stored as negative amounts so the lines always sum to the total; keeping them
  -- positive and subtracting elsewhere is how a total stops matching its own line items.
  for v_line in select * from jsonb_array_elements(p_lines) loop
    if (v_line ->> 'kind') in ('discount', 'credit') then
      v_discount := v_discount + abs((v_line ->> 'amount_cents')::integer);
    else
      v_subtotal := v_subtotal + (v_line ->> 'amount_cents')::integer;
    end if;
  end loop;

  v_total := v_subtotal - v_discount;

  -- Tax is deliberately zero until a tax service is integrated (SA-3.2 out of scope).
  if p_provider_total_cents is null then
    v_reconciliation := 'not_applicable';
  elsif p_provider_total_cents = v_total then
    v_reconciliation := 'matched';
  else
    v_reconciliation := 'mismatched';
  end if;

  v_number := public.allocate_invoice_number(coalesce(p_paid_at, now()));

  insert into public.invoices (
    number, tenant_id, subscription_id, status, period_start, period_end,
    subtotal_cents, discount_cents, tax_cents, total_cents,
    provider, provider_payment_id, provider_total_cents, reconciliation,
    issued_at, paid_at
  ) values (
    v_number, p_tenant_id, p_subscription_id, 'paid', p_period_start, p_period_end,
    v_subtotal, v_discount, 0, v_total,
    p_provider, p_provider_payment_id, p_provider_total_cents, v_reconciliation,
    coalesce(p_paid_at, now()), coalesce(p_paid_at, now())
  ) returning id into v_id;

  for v_line in select * from jsonb_array_elements(p_lines) loop
    insert into public.invoice_lines (
      invoice_id, position, kind, label, quantity, included_qty, unit_cents, amount_cents
    ) values (
      v_id,
      v_position,
      (v_line ->> 'kind')::public.invoice_line_kind,
      v_line ->> 'label',
      coalesce((v_line ->> 'quantity')::numeric, 1),
      (v_line ->> 'included_qty')::numeric,
      coalesce((v_line ->> 'unit_cents')::integer, 0),
      (v_line ->> 'amount_cents')::integer
    );
    v_position := v_position + 1;
  end loop;

  return query select v_id, v_number, true, v_reconciliation;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_subscription_from_checkout(p_tenant_id uuid, p_plan_id uuid, p_billing_cycle billing_cycle, p_whop_membership_id text, p_trial_days integer)
 RETURNS TABLE(subscription_id uuid, created boolean, status subscription_status)
 LANGUAGE plpgsql
AS $function$
declare
  v_existing public.subscriptions%rowtype;
  v_id       uuid;
  v_status   public.subscription_status;
  v_now      timestamptz := now();
  v_trial_ends timestamptz;
begin
  select * into v_existing from public.subscriptions where tenant_id = p_tenant_id for update;

  if found then
    -- Keep the membership id fresh even when we did not create anything: the webhook often knows
    -- it when the return handler did not.
    if p_whop_membership_id is not null and v_existing.whop_membership_id is null then
      update public.subscriptions
         set whop_membership_id = p_whop_membership_id
       where id = v_existing.id;
    end if;
    return query select v_existing.id, false, v_existing.status;
    return;
  end if;

  -- A trial subscription is `trialing`, which our access rules already treat as full access. Zero
  -- trial days means they are paying from today.
  if p_trial_days > 0 then
    v_status := 'trialing';
    v_trial_ends := v_now + make_interval(days => p_trial_days);
  else
    v_status := 'active';
    v_trial_ends := null;
  end if;

  insert into public.subscriptions (
    tenant_id, plan_id, status, billing_cycle, started_at,
    current_period_start, current_period_end, trial_ends_at, whop_membership_id
  ) values (
    p_tenant_id, p_plan_id, v_status, p_billing_cycle, v_now,
    v_now, public.period_end_for(v_now, p_billing_cycle), v_trial_ends, p_whop_membership_id
  ) returning id into v_id;

  -- The tenant has paid (or started a trial), so it is no longer provisioning and the signup
  -- journey is over.
  update public.tenants
     set status = 'active',
         onboarding_state = 'completed'
   where id = p_tenant_id;

  return query select v_id, true, v_status;
end;
$function$;

CREATE OR REPLACE FUNCTION public.create_tenant_with_owner(p_tenant_name text, p_owner_name text, p_owner_email text, p_owner_password_hash text)
 RETURNS TABLE(tenant_id uuid, user_id uuid)
 LANGUAGE plpgsql
AS $function$
declare
  v_tenant_id uuid;
  v_user_id uuid;
begin
  insert into tenants (name, status) values (p_tenant_name, 'provisioning') returning id into v_tenant_id;
  insert into users (email, password_hash, name) values (lower(p_owner_email), p_owner_password_hash, p_owner_name) returning id into v_user_id;
  insert into tenant_users (tenant_id, user_id, role, accepted_at) values (v_tenant_id, v_user_id, 'owner', now());
  return query select v_tenant_id, v_user_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.extend_trial(p_subscription_id uuid, p_days integer)
 RETURNS TABLE(trial_ends_at timestamp with time zone, current_period_end timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
declare
  v_row public.subscriptions%rowtype;
begin
  if p_days <= 0 then
    raise exception 'an extension must be at least one day';
  end if;

  select * into v_row from public.subscriptions where id = p_subscription_id for update;

  if not found then raise exception 'no such subscription'; end if;
  if v_row.status <> 'trialing' then
    raise exception 'only a trialing subscription can be extended (this one is %)', v_row.status;
  end if;
  if v_row.trial_ends_at is null then
    raise exception 'this subscription has no trial end date';
  end if;

  update public.subscriptions
     set trial_ends_at = v_row.trial_ends_at + make_interval(days => p_days),
         current_period_end = coalesce(v_row.current_period_end, v_row.trial_ends_at)
                              + make_interval(days => p_days)
   where id = p_subscription_id
  returning subscriptions.trial_ends_at, subscriptions.current_period_end
  into trial_ends_at, current_period_end;

  return next;
end;
$function$;

CREATE OR REPLACE FUNCTION public.mark_overdue_invoices()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare v_count integer;
begin
  with moved as (
    update public.invoices
       set status = 'overdue'
     where status = 'issued'
       and due_at is not null
       and due_at < now()
    returning 1
  )
  select count(*) into v_count from moved;

  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.monthly_equivalent_cents(p_plan_id uuid, p_cycle billing_cycle)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(round(
    case p_cycle
      when 'monthly'   then pp.price_monthly_cents::numeric
      when 'quarterly' then pp.price_quarterly_cents::numeric / 3
      when 'yearly'    then pp.price_yearly_cents::numeric / 12
    end
  )::integer, 0)
  from public.plan_prices pp
  where pp.plan_id = p_plan_id;
$function$;

CREATE OR REPLACE FUNCTION public.outstanding_legal_documents(p_user_id uuid)
 RETURNS SETOF current_legal_documents
 LANGUAGE sql
 STABLE
AS $function$
  select c.*
    from public.current_legal_documents c
   where c.requires_reacceptance
     and not exists (
       select 1 from public.legal_acceptances a
        where a.user_id = p_user_id and a.document_id = c.id
     );
$function$;

CREATE OR REPLACE FUNCTION public.period_end_for(p_start timestamp with time zone, p_cycle billing_cycle)
 RETURNS timestamp with time zone
 LANGUAGE sql
 IMMUTABLE
AS $function$
  select case p_cycle
    when 'monthly'   then p_start + interval '1 month'
    when 'quarterly' then p_start + interval '3 months'
    else                  p_start + interval '1 year'
  end;
$function$;

CREATE OR REPLACE FUNCTION public.prune_rate_limits()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare v_count integer;
begin
  with removed as (
    delete from public.rate_limits where window_start < now() - interval '1 day' returning 1
  )
  select count(*) into v_count from removed;
  return v_count;
end;
$function$;

CREATE OR REPLACE FUNCTION public.publish_legal_document(p_doc_type legal_doc_type, p_title text, p_content text, p_effective_date date, p_change_summary text, p_requires_reacceptance boolean, p_published_by uuid)
 RETURNS legal_documents
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_next integer;
  v_row  public.legal_documents;
begin
  if length(coalesce(trim(p_content), '')) < 50 then
    raise exception 'the document text is too short to be a real legal document';
  end if;

  perform pg_advisory_xact_lock(hashtext('legal_document:' || p_doc_type::text));

  select coalesce(max(version), 0) + 1 into v_next
    from public.legal_documents
   where doc_type = p_doc_type;

  insert into public.legal_documents
    (doc_type, version, effective_date, title, content, change_summary,
     requires_reacceptance, is_draft, published_by)
  values
    (p_doc_type, v_next, p_effective_date, p_title, p_content, p_change_summary,
     coalesce(p_requires_reacceptance, true), false, p_published_by)
  returning * into v_row;

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.rebuild_usage_totals()
 RETURNS integer
 LANGUAGE plpgsql
AS $function$
declare
  v_rows integer;
begin
  delete from usage_totals where true;

  insert into usage_totals (tenant_id, meter_key, period_start, used_qty, updated_at)
  select tenant_id, meter_key, period_start, sum(qty)::integer, now()
  from usage_events
  group by tenant_id, meter_key, period_start;

  get diagnostics v_rows = row_count;
  return v_rows;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_legal_acceptance(p_user_id uuid, p_document_id uuid, p_ip inet, p_user_agent text, p_context text)
 RETURNS legal_acceptances
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_doc public.legal_documents;
  v_row public.legal_acceptances;
begin
  select * into v_doc from public.legal_documents where id = p_document_id;
  if not found then raise exception 'no such legal document'; end if;

  insert into public.legal_acceptances
    (user_id, document_id, doc_type, version, ip, user_agent, context)
  values
    (p_user_id, p_document_id, v_doc.doc_type, v_doc.version, p_ip, p_user_agent,
     coalesce(p_context, 'signup'))
  on conflict (user_id, document_id) do nothing
  returning * into v_row;

  if v_row.id is null then
    select * into v_row from public.legal_acceptances
     where user_id = p_user_id and document_id = p_document_id;
  end if;

  return v_row;
end;
$function$;

CREATE OR REPLACE FUNCTION public.record_usage(p_tenant_id uuid, p_meter_key text, p_qty integer, p_idempotency_key text, p_ref text DEFAULT NULL::text)
 RETURNS TABLE(recorded boolean, new_total integer, billing_period_start timestamp with time zone)
 LANGUAGE plpgsql
AS $function$
declare
  v_period timestamptz;
  v_inserted boolean := false;
  v_total integer;
begin
  v_period := tenant_current_period_start(p_tenant_id);

  insert into usage_events (tenant_id, meter_key, qty, ref, idempotency_key, period_start)
  values (p_tenant_id, p_meter_key, p_qty, p_ref, p_idempotency_key, v_period)
  on conflict (tenant_id, meter_key, idempotency_key) do nothing;

  v_inserted := found;

  if v_inserted then
    insert into usage_totals as ut (tenant_id, meter_key, period_start, used_qty, updated_at)
    values (p_tenant_id, p_meter_key, v_period, p_qty, now())
    on conflict (tenant_id, meter_key, period_start) do update
      set used_qty = ut.used_qty + excluded.used_qty,
          updated_at = now();
  end if;

  select t.used_qty into v_total
  from usage_totals t
  where t.tenant_id = p_tenant_id and t.meter_key = p_meter_key and t.period_start = v_period;

  return query select v_inserted, coalesce(v_total, 0), v_period;
end;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_signup_verification(p_user_id uuid, p_new_email text, p_token_hash text, p_expires_at timestamp with time zone)
 RETURNS TABLE(verification_id uuid, email text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user public.users%rowtype;
  v_verification_id uuid;
  v_email text;
  v_last_created_at timestamptz;
begin
  select account.*
    into v_user
    from public.users account
   where account.id = p_user_id
   for update;

  if not found or v_user.status <> 'pending_verification' then
    raise exception using errcode = 'P0001', message = 'ACCOUNT_NOT_PENDING_VERIFICATION';
  end if;

  select max(created_at)
    into v_last_created_at
    from public.user_invitations
   where user_id = p_user_id
     and purpose = 'email_verification';

  -- A typo correction must work immediately after signup. Only a resend to the unchanged
  -- address is rate-limited; otherwise the screen would identify a typo and then trap the user.
  if v_last_created_at is not null
     and v_last_created_at > now() - interval '60 seconds'
     and coalesce(nullif(lower(btrim(p_new_email)), ''), v_user.email) = v_user.email then
    raise exception using errcode = 'P0001', message = 'VERIFICATION_RESEND_TOO_SOON';
  end if;

  v_email := coalesce(nullif(lower(btrim(p_new_email)), ''), v_user.email);

  update public.users
     set email = v_email
   where id = p_user_id;

  update public.user_invitations
     set accepted_at = now()
   where user_id = p_user_id
     and purpose = 'email_verification'
     and accepted_at is null;

  insert into public.user_invitations (user_id, token_hash, purpose, expires_at)
  values (
    p_user_id,
    p_token_hash,
    'email_verification'::public.user_token_purpose,
    p_expires_at
  )
  returning id into v_verification_id;

  return query select v_verification_id, v_email;
end;
$function$;

CREATE OR REPLACE FUNCTION public.refresh_tenant_entitlement(p_tenant_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
declare
  r record;
  v_plan record;
  v_period timestamptz;
  v_meters jsonb := '{}'::jsonb;
  v_key text;
  v_value jsonb;
  v_used integer;
  v_entitlement jsonb;
  v_access text;
begin
  select * into r from resolve_tenant_entitlement(p_tenant_id);

  -- No live subscription: an explicit "nothing" object rather than a missing row, so callers
  -- never have to distinguish "not computed" from "entitled to nothing".
  if r.plan_id is null then
    v_entitlement := jsonb_build_object(
      'tenant_id', p_tenant_id,
      'plan_code', null,
      'plan_version', null,
      'status', null,
      'access', 'none',
      'computed_at', now(),
      'features', '[]'::jsonb,
      'meters', '{}'::jsonb,
      'limits', jsonb_build_object('max_seats', null)
    );
  else
    select code, version into v_plan from plans where id = r.plan_id;
    v_period := tenant_current_period_start(p_tenant_id);

    -- Fold live usage into each meter, so the agent app can render a usage bar without a
    -- second query and without knowing how usage is stored.
    for v_key, v_value in select * from jsonb_each(r.meter_allowances)
    loop
      select coalesce(ut.used_qty, 0) into v_used
      from usage_totals ut
      where ut.tenant_id = p_tenant_id and ut.meter_key = v_key and ut.period_start = v_period;

      v_meters := v_meters || jsonb_build_object(
        v_key,
        jsonb_build_object(
          'included', v_value->'included',
          'hard_cap', v_value->'hard_cap',
          'used', coalesce(v_used, 0)
        )
      );
    end loop;

    -- Mirrors accessLevelForStatus() in lib/subscriptions/access.ts. A suspended tenant keeps a
    -- READ-ONLY entitlement, never an empty one: suspend the doing, preserve the seeing.
    v_access := case r.subscription_status
      when 'suspended' then 'read_only'
      when 'paused' then 'read_only'
      when 'cancelled' then 'none'
      else 'full'
    end;

    v_entitlement := jsonb_build_object(
      'tenant_id', p_tenant_id,
      'plan_code', v_plan.code,
      'plan_version', v_plan.version,
      'status', r.subscription_status,
      'access', v_access,
      'computed_at', now(),
      'features', to_jsonb(r.feature_keys),
      'meters', v_meters,
      'limits', jsonb_build_object('max_seats', r.max_seats),
      'period_start', v_period
    );
  end if;

  insert into tenant_entitlements as te (tenant_id, entitlement, computed_at, version)
  values (p_tenant_id, v_entitlement, now(), 1)
  on conflict (tenant_id) do update
    set entitlement = excluded.entitlement,
        computed_at = now(),
        version = te.version + 1;

  return v_entitlement;
end;
$function$;

CREATE OR REPLACE FUNCTION public.request_credit_note(p_tenant_id uuid, p_invoice_id uuid, p_type credit_note_type, p_amount_cents integer, p_reason_code credit_reason, p_reason_text text, p_requested_by uuid, p_threshold_cents integer)
 RETURNS TABLE(credit_note_id uuid, number text, status credit_note_status)
 LANGUAGE plpgsql
AS $function$
declare
  v_number text;
  v_id     uuid;
  v_status public.credit_note_status;
begin
  if p_amount_cents <= 0 then
    raise exception 'a credit note must be for more than zero';
  end if;

  -- Only a refund moves money, so only a refund is gated. A credit or a waiver costs revenue but
  -- cannot drain the bank account, which is what the threshold protects.
  if p_type = 'refund' and p_amount_cents > p_threshold_cents then
    v_status := 'pending_approval';
  else
    v_status := 'approved';
  end if;

  v_number := public.allocate_document_number('CN', now());

  insert into public.credit_notes (
    number, tenant_id, invoice_id, type, amount_cents,
    reason_code, reason_text, status, requested_by,
    approved_at
  ) values (
    v_number, p_tenant_id, p_invoice_id, p_type, p_amount_cents,
    p_reason_code, p_reason_text, v_status, p_requested_by,
    case when v_status = 'approved' then now() else null end
  ) returning id into v_id;

  return query select v_id, v_number, v_status;
end;
$function$;

CREATE OR REPLACE FUNCTION public.save_signup_business_profile(p_user_id uuid, p_business_name text, p_npn text, p_primary_state text, p_products_sold text[], p_monthly_volume_range text, p_lead_sources text[], p_lead_source_other text, p_recommended_setup_steps text[])
 RETURNS TABLE(tenant_id uuid, onboarding_state text)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
#variable_conflict use_column
declare
  v_tenant_id uuid;
begin
  select membership.tenant_id
    into v_tenant_id
    from public.tenant_users membership
    join public.users account on account.id = membership.user_id
   where membership.user_id = p_user_id
     and membership.role = 'owner'
     and account.status = 'active'
   for update of membership;

  if not found then
    raise exception using errcode = 'P0001', message = 'VERIFIED_OWNER_NOT_FOUND';
  end if;

  if not exists (
    select 1
      from public.tenants tenant
     where tenant.id = v_tenant_id
       and tenant.onboarding_state in ('business_profile', 'ready_for_checkout')
  ) then
    raise exception using errcode = 'P0001', message = 'BUSINESS_PROFILE_NOT_AVAILABLE';
  end if;

  insert into public.business_profiles (
    tenant_id, business_name, npn, primary_state, products_sold,
    monthly_volume_range, lead_sources, lead_source_other,
    recommended_setup_steps, completed_at, updated_at
  )
  values (
    v_tenant_id,
    btrim(p_business_name),
    btrim(p_npn),
    upper(btrim(p_primary_state)),
    p_products_sold,
    p_monthly_volume_range,
    p_lead_sources,
    nullif(btrim(p_lead_source_other), ''),
    p_recommended_setup_steps,
    now(),
    now()
  )
  on conflict (tenant_id) do update set
    business_name = excluded.business_name,
    npn = excluded.npn,
    primary_state = excluded.primary_state,
    products_sold = excluded.products_sold,
    monthly_volume_range = excluded.monthly_volume_range,
    lead_sources = excluded.lead_sources,
    lead_source_other = excluded.lead_source_other,
    recommended_setup_steps = excluded.recommended_setup_steps,
    completed_at = now(),
    updated_at = now();

  update public.tenants
     set name = btrim(p_business_name),
         onboarding_state = 'ready_for_checkout'
   where id = v_tenant_id;

  return query select v_tenant_id, 'ready_for_checkout'::text;
end;
$function$;

CREATE OR REPLACE FUNCTION public.self_serve_signup(p_name text, p_email text, p_password_hash text, p_phone text, p_plan_id uuid, p_billing_cycle billing_cycle, p_token_hash text, p_expires_at timestamp with time zone)
 RETURNS TABLE(user_id uuid, tenant_id uuid, verification_id uuid)
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
declare
  v_user_id uuid;
  v_tenant_id uuid;
  v_verification_id uuid;
  v_plan public.plans%rowtype;
  v_cycle_available boolean;
begin
  select p.*
    into v_plan
    from public.plans p
   where p.id = p_plan_id
     and p.is_public
     and not p.is_archived
     and p.version = (
       select max(latest.version)
         from public.plans latest
        where latest.code = p.code
     )
   for share;

  if not found then
    raise exception using errcode = 'P0001', message = 'PLAN_UNAVAILABLE';
  end if;

  select case p_billing_cycle
    when 'monthly' then prices.price_monthly_cents is not null
    when 'quarterly' then prices.price_quarterly_cents is not null
    when 'yearly' then prices.price_yearly_cents is not null
  end
    into v_cycle_available
    from public.plan_prices prices
   where prices.plan_id = p_plan_id;

  if coalesce(v_cycle_available, false) is not true then
    raise exception using errcode = 'P0001', message = 'BILLING_CYCLE_UNAVAILABLE';
  end if;

  insert into public.users (email, password_hash, name, phone, status)
  values (
    lower(btrim(p_email)),
    p_password_hash,
    btrim(p_name),
    nullif(btrim(p_phone), ''),
    'pending_verification'::public.user_status
  )
  returning id into v_user_id;

  insert into public.tenants (name, status, onboarding_state)
  values (btrim(p_name) || '''s Workspace', 'provisioning', 'pending_verification')
  returning id into v_tenant_id;

  insert into public.tenant_users (tenant_id, user_id, role)
  values (v_tenant_id, v_user_id, 'owner');

  insert into public.signup_selections (tenant_id, plan_id, billing_cycle)
  values (v_tenant_id, p_plan_id, p_billing_cycle);

  insert into public.user_invitations (user_id, token_hash, purpose, expires_at)
  values (
    v_user_id,
    p_token_hash,
    'email_verification'::public.user_token_purpose,
    p_expires_at
  )
  returning id into v_verification_id;

  return query select v_user_id, v_tenant_id, v_verification_id;
end;
$function$;

CREATE OR REPLACE FUNCTION public.tenant_current_period_start(p_tenant_id uuid)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE
AS $function$
  select coalesce(
    (
      select s.current_period_start
      from subscriptions s
      where s.tenant_id = p_tenant_id and s.status <> 'cancelled'
      order by s.created_at desc
      limit 1
    ),
    date_trunc('month', now())
  );
$function$;

CREATE OR REPLACE FUNCTION public.tenant_current_plan(p_tenant_id uuid)
 RETURNS uuid
 LANGUAGE sql
 STABLE
AS $function$
  select s.plan_id
  from subscriptions s
  where s.tenant_id = p_tenant_id and s.status <> 'cancelled'
  order by s.created_at desc
  limit 1;
$function$;

CREATE OR REPLACE FUNCTION public.tenant_seats_used(p_tenant_id uuid)
 RETURNS integer
 LANGUAGE sql
 STABLE
AS $function$
  select count(*)::integer
  from tenant_users tu
  join users u on u.id = tu.user_id
  where tu.tenant_id = p_tenant_id and u.status in ('active', 'suspended');
$function$;


