drop policy if exists tenant_users_scoped on public.tenant_users;
create policy tenant_users_scoped on public.tenant_users for select to public
  using ((tenant_id = (current_setting('app.tenant_id'::text, true))::uuid));
drop policy if exists tenant_self_read on public.tenants;
create policy tenant_self_read on public.tenants for select to public
  using ((id = (current_setting('app.tenant_id'::text, true))::uuid));
drop policy if exists users_scoped_to_tenant on public.users;
create policy users_scoped_to_tenant on public.users for select to public
  using ((id IN ( SELECT tu.user_id
   FROM tenant_users tu
  WHERE (tu.tenant_id = (current_setting('app.tenant_id'::text, true))::uuid))));

